"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if _is_blank(value):
        value = 0

    try:
        with localcontext() as context:
            context.prec = 50
            cents = (Decimal(str(value)) * Decimal(100)).to_integral_value(
                rounding=ROUND_HALF_UP
            )
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"ANN_REV is not numeric: {value!r}") from exc

    rendered = str(cents).zfill(width)
    if len(rendered) > width:
        raise ValueError(f"ANN_REV cents exceed the {width}-character layout field")
    return rendered


def format_account(row: dict) -> str:
    """Build one 77-character legacy EXPORT_ACCT record."""
    credit_hold = row.get("CRED_HOLD", "")
    if _is_blank(credit_hold):
        credit_hold = "N"
    else:
        credit_hold = str(credit_hold)

    create_date = row.get("CREATE_DT", "")
    if _is_blank(create_date):
        create_date = "00000000"
    else:
        create_date = str(create_date)

    record = (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _zpad_cents(row.get("ANN_REV", ""), 15)
        + credit_hold
        + create_date
    )

    if len(record) != 77:
        raise ValueError("CRED_HOLD and CREATE_DT must occupy 1 and 8 characters")
    return record
